import json,pathlib,copy
from bs4 import BeautifulSoup
r=pathlib.Path('work/research-2026');p=json.load(open(r/'reviewed.json'));xs=json.load(open(r/'verified-sites140-next100-review.json'));before={};dec=[]
assert not (r/'featured138-before.json').exists()
fix={44:'An energy-policy advocacy organization promoting affordable and reliable energy and infrastructure development.',83:'Operates a capital platform for energy projects, including transferable tax credits and financing; securities services are offered through a separately named broker-dealer.',84:'Operates the Crux capital platform for energy-project financing and transferable tax credits; securities services are provided through a separate broker-dealer.',85:'Develops blockchain-based index infrastructure for digital assets.',98:'Provides sensors and software that help cities assess streets, sidewalks and infrastructure assets.'}
special={9:'The official legal disclosure explicitly distinguishes CohnReznick LLP, a licensed CPA firm providing attest services, from CohnReznick Advisory LLC, which provides tax and consulting services.',24:'Caturus’s official operations page explicitly names Commonwealth LNG and describes its Cameron, Louisiana export-facility development. Planned facilities and design capacity are not treated as operating assets.',26:'The official site explicitly names Community Bankshares, Inc. and its subsidiary partners Phoenix Lender Services and Thomas Financial Group.',37:'The official Portuguese-language site names the Brazilian financial-institution confederation and describes sector representation and policy coordination.',40:'The official Spanish-language site explicitly names Consejo Coordinador Empresarial and describes Mexican business-policy advocacy; the associated foundation is not substituted for the council.',43:'The coalition’s own About text explicitly names Consumer Choice in Payment Coalition and its cash-payment advocacy, despite minor wording variations in the site title and footer.',47:'The CommonSpirit facility page explicitly identifies Continuing Care Hospital in Lexington and its location within Saint Joseph Hospital. The facility is not conflated with every CommonSpirit entity.',50:'The official CTR page describes Hell’s Kitchen geothermal and critical-minerals development. Future generation and extraction plans are not presented as completed operations.',56:'The official COR site identifies its Portland waste collection, recycling, transfer and construction services. B Corp branding alone is not treated as public ownership or nonprofit status.',67:'The CDFA About body names the Council of Development Finance Agencies and describes membership across public, private and nonprofit development-finance organizations.',70:'The official page explicitly links CQT Weapon Systems to Center for Quality Training International, LLC and describes its engineering and manufacturing work.',71:'The official CRCD Enterprises site describes its contracting and paid workforce-training services and identifies its South Los Angeles headquarters.',75:'The official CREI project descriptions name CREI Holdings and distinguish completed housing developments from projects described as under construction. Older completion targets are not assumed achieved.',79:'The official About body names Crown Point Technologies, LLC, its Maryland location and software/data-engineering activity.',81:'CrunchAtlas’s official body describes cybersecurity investigation tools. Demonstration scenarios and internal performance claims are not treated as independently verified incidents or results.',83:'The Crux site identifies Crux Climate, LLC in its footer and separately identifies Crux Capital Securities, LLC as broker-dealer. The source records are retained separately; this review does not merge them.',84:'The Crux site identifies Crux Climate, LLC in its footer and separately identifies Crux Capital Securities, LLC as broker-dealer. Broker-dealer registration is not transferred to the platform entity.',88:'The official CTS site names CTS Cement Manufacturing Corporation, its Garden Grove address and cement/concrete product lines.'}
for n,v in enumerate(xs):
 if v['decision']!='confirmed' or n==80:continue
 i=v['id'];assert p[i]['name']==v['original_name'] and p[i]['review_outcome']!='confirmed';before[i]=copy.deepcopy(p[i]);note=special.get(n,'Official organization body text identifies this organization and supports the activity summarized. Existing ownership evidence is retained without inferring additional ownership from its name.')
 p[i].update(description=fix.get(n,v['description']),notes=note,identity_evidence=note,review_outcome='confirmed',checked_at='2026-09-13',as_of='2026-09-13')
 e=v['fetched_evidence'][0];assert e['http_status']==200
 s=BeautifulSoup(open(e['cache_path']).read(),'html.parser')
 for t in s(['script','style','nav','header']):t.decompose()
 body=' '.join(s.stripped_strings)
 ss={s['url']:s for s in p[i]['sources']};ss[e['url']]={'url':e['url'],'label':'Official organization evidence','claim':note};p[i]['sources']=list(ss.values());dec.append(dict(id=i,name=p[i]['name'],decision='confirmed',notes=note,fetched_evidence=v['fetched_evidence'],reviewed_body=body))
(r/'featured138-before.json').write_text(json.dumps(before,indent=2)+'\n');(r/'featured138-decisions.json').write_text(json.dumps(dec,indent=2)+'\n')
(r/'featured138-deferred.json').write_text(json.dumps([dict(id=xs[80]['id'],name=xs[80]['original_name'],reason='Short mission statement refers to an unspecified state; exact context and clearer activity evidence remain needed.')],indent=2)+'\n')
for f in [r/'reviewed.json',pathlib.Path('outputs/2026-research-trial/profiles.json')]:f.write_text(json.dumps(p,ensure_ascii=False,indent=2)+'\n')
pathlib.Path('lobbying-map/research/reviewed-2026.json').write_text(json.dumps(p,ensure_ascii=False));print(len(dec),'identity confirmations saved')
